/*
 * mkrusttests.c -- turn a reference dump into a Rust test module.
 *
 * The dump is the oracle: it is what a real machine did, case by case.  This
 * emits one `#[test]` per case that replays the case against
 * `tos_api::vdi::dispatch` (areas VDI and VDI-RASTER) or
 * `tos_api::aes::dispatch` (area AES) and compares every array against the
 * record.  The comparison itself lives in the harness; this only lays out the
 * inputs and the record index, so the generated file stays readable and
 * reviewable.
 *
 * The expected outputs are NOT copied into the generated code: it embeds the
 * dump with `include_bytes!` and indexes into it. The dump therefore stays
 * the single source of truth, and regenerating after a new measurement
 * cannot leave stale expectations behind.
 *
 * The AREA IS THE DUMP'S TO STATE, not the caller's to guess: the header
 * carries it, and the three case-table forms differ in column count (five for
 * the VDI form, seven for the AES form and seven again -- but different ones
 * -- for the raster form, core/cases.h), so reading a table with the wrong
 * form would silently mis-slice every line.  Which emitter runs is therefore
 * decided by td_header_parse, and a dump whose area has no emitter is refused
 * rather than half-generated.
 *
 * usage: mkrusttests CASES.TSV DUMP.BIN DUMP_INCLUDE_PATH OUT.rs
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "cases.h"

static struct td_case_table table;
static struct td_aes_case_table aes_table;
static struct td_rast_case_table rast_table;

/* A Rust identifier fragment from a free-text comment. */
static void slug(const char *s, char *out, size_t out_size)
{
	size_t n = 0;
	int prev_us = 1;   /* suppress a leading underscore */

	for (; *s && n + 1 < out_size; s++) {
		char c = *s;
		if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')) {
			out[n++] = c;
			prev_us = 0;
		} else if (c >= 'A' && c <= 'Z') {
			out[n++] = (char)(c - 'A' + 'a');
			prev_us = 0;
		} else if (!prev_us) {
			out[n++] = '_';
			prev_us = 1;
		}
	}
	while (n > 0 && out[n - 1] == '_')
		n--;
	out[n] = '\0';
	if (n == 0)
		snprintf(out, out_size, "case");
}

static void escape(const char *s, char *out, size_t out_size)
{
	size_t n = 0;

	for (; *s && n + 2 < out_size; s++) {
		if (*s == '"' || *s == '\\')
			out[n++] = '\\';
		out[n++] = *s;
	}
	out[n] = '\0';
}

static void emit_list(FILE *f, const int16_t *v, uint16_t n)
{
	uint16_t i;

	if (n == 0) {
		fputs("&[]", f);
		return;
	}
	fputs("&[", f);
	for (i = 0; i < n; i++)
		fprintf(f, "%s%d", i ? ", " : "", v[i]);
	fputc(']', f);
}

/*
 * The addr_in column of one AES line, as the Rust harness spells it.
 *
 * A plant names a BUFFER BY NUMBER, never an address -- the same reason the
 * case table cannot state one (core/cases.h).  The harness holds the four
 * buffers the dumper holds, laid with the identical pattern
 * (tos-api/tests/aes_reference/harness.rs, buf_fill / buffers), so what the
 * replay hands the call is the same bytes at its own address, and a slot that
 * still holds what was planted compares as the buffer TOKEN on both sides.
 */
static void emit_plants(FILE *f, const struct td_aes_plant *p, uint16_t n)
{
	uint16_t i;

	if (n == 0) {
		fputs("&[]", f);
		return;
	}
	fputs("&[", f);
	for (i = 0; i < n; i++)
		fprintf(f, "%sPlant { kind: Kind::%s, slot: %d, buffer: %d }",
		        i ? ", " : "",
		        p[i].kind == TD_AES_PLANT_ADDRIN ? "AddrIn" : "IntIn",
		        p[i].where, p[i].buffer);
	fputc(']', f);
}

/* One MFDB spec of a raster case, as the case table states it. */
static void emit_form(FILE *f, const struct td_rast_mfdb *m)
{
	fprintf(f, "Form { buffer: %d, w: %d, h: %d, wdwidth: %d, stand: %d, "
	           "nplanes: %d }",
	        m->buffer, m->w, m->h, m->wdwidth, m->stand, m->nplanes);
}

/* ------------------------------------------------------------------ */
/* VDI emitter                                                         */
/* ------------------------------------------------------------------ */

static int emit_vdi(FILE *f, const struct td_header *h, const char *cases_path,
                    const char *dump_path, const char *include_path,
                    const char *out_path)
{
	uint16_t i;

	fprintf(f,
"//! GENERATED by tosdump/host/mkrusttests -- do not edit.\n"
"//!\n"
"//! One test per case in `%s`, replayed against `tos_api::vdi` and\n"
"//! compared with what a real machine did, recorded in `%s`\n"
"//! (build %s, case table CRC %08X, %u cases).\n"
"//!\n"
"//! The expected values are not written out here: the dump is embedded and\n"
"//! indexed, so it stays the single source of truth and a regenerated file\n"
"//! cannot carry stale expectations. Regenerate with:\n"
"//!\n"
"//!     tosdump/host/build/mkrusttests \\\\\n"
"//!         %s \\\\\n"
"//!         %s \\\\\n"
"//!         %s \\\\\n"
"//!         %s\n"
"\n"
"use crate::harness::{check, Call, Case};\n"
"\n"
"static DUMP: &[u8] = include_bytes!(\"%s\");\n",
	        cases_path, dump_path, h->build_id, h->case_crc, h->record_count,
	        cases_path, dump_path, include_path, out_path, include_path);

	for (i = 0; i < table.count; i++) {
		const struct td_case *c = &table.cases[i];
		char name[96], cmt[TD_COMMENT_LEN * 2];

		slug(c->comment, name, sizeof name);
		escape(c->comment, cmt, sizeof cmt);

		fprintf(f, "\n#[test]\nfn case_%04u_op%03d", c->line, c->opcode);
		if (c->sub)
			fprintf(f, "_sub%d", c->sub);
		fprintf(f, "_%s() {\n", name);
		fprintf(f, "    check(DUMP, &Case {\n");
		fprintf(f, "        prelude: &[");
		{
			uint16_t k;
			for (k = 0; k < c->prelude_count; k++) {
				const struct td_prelude *p =
					&table.preludes[c->prelude_first + k];
				fprintf(f, "\n            Call { opcode: %d, sub: %d, intin: ",
				        p->opcode, p->sub);
				emit_list(f, p->intin, p->n_intin);
				fprintf(f, ", ptsin: ");
				emit_list(f, p->ptsin, p->n_ptsin);
				fprintf(f, " },");
			}
			if (c->prelude_count)
				fprintf(f, "\n        ");
		}
		fprintf(f, "],\n");
		fprintf(f, "        id: %u,\n        rec: %u,\n", c->line, i);
		fprintf(f, "        opcode: %d,\n        sub: %d,\n", c->opcode, c->sub);
		fprintf(f, "        intin: ");
		emit_list(f, c->intin, c->n_intin);
		fprintf(f, ",\n        ptsin: ");
		emit_list(f, c->ptsin, c->n_ptsin);
		fprintf(f, ",\n        comment: \"%s\",\n    });\n}\n", cmt);
	}
	return (int)table.count;
}

/* ------------------------------------------------------------------ */
/* AES emitter                                                         */
/* ------------------------------------------------------------------ */
/*
 * The AES case carries FIVE declared counts, not two derived ones, and that
 * is the whole difference to the VDI form: in the AES all five control slots
 * are inputs and the dispatcher's marshalling is driven by the counts alone
 * (EmuTOS aes/gemsuper.c:428-448).  IN_LEN independent of the number of
 * values listed is what lets a case measure "the surplus input words are
 * copied in as poison"; OUT_LEN independent of what the handler writes is
 * what lets it measure "the surplus output words stay poisoned".  So the
 * counts are emitted verbatim and never recomputed from the value list.
 *
 * The AES table also carries something no other form has: the RESET
 * DIRECTIVE (core/cases.h, "!reset").  It is a property of the TABLE, not of
 * a case -- the runner issues it before every case out of ct->reset
 * (core/runner_aes.c:154) -- so it is emitted once, as a `Table` the whole
 * module shares, and every case is checked against that table rather than
 * against the bare dump.  Emitting it is not optional: a round-2 table
 * replayed WITHOUT its reset measures a different thing than the dump it is
 * compared against, and would fail or pass for reasons that have nothing to
 * do with the AES.
 *
 * The `Table` also carries the table's NAME, because a case id is a physical
 * line number IN THAT FILE and two tables therefore reuse ids: cases/aes-r1.tsv
 * and cases/aes-r2-wind.tsv both have a case 228.  Anything the harness keys
 * on a case id (its Delta list) would be ambiguous without the name.
 */
/* Why an emitter refused, so main can name it.  NULL until one does. */
static const char *emit_refusal;

static int emit_aes(FILE *f, const struct td_header *h, const char *cases_path,
                    const char *dump_path, const char *include_path,
                    const char *out_path)
{
	const char *reset_name;
	const char *imports;
	const char *addrin_note;
	int any_plant = 0;
	uint16_t i;

	/* Refused rather than defaulted, for the same reason the loader refuses
	 * an unknown "!reset" name (core/cases.h): defaulting would silently
	 * generate a round-2 module that replays without round 2's reset. */
	if (aes_table.reset == TD_AES_RESET_NONE)
		reset_name = "None";
	else if (aes_table.reset == TD_AES_RESET_WIND_NEW)
		reset_name = "WindNew";
	else {
		emit_refusal = "declares a reset this generator cannot emit";
		return -1;
	}

	/*
	 * The imports the module actually uses.  An unused one is a warning and
	 * a generated file must not add one, so `Call` goes in only when the
	 * table has preludes and `Kind`/`Plant` only when some line names a
	 * buffer -- an eight column table that plants nothing anywhere (which is
	 * a legal table: cases/aes-m05-addrin.tsv's section A is exactly that
	 * line) needs neither.
	 */
	for (i = 0; i < aes_table.count; i++)
		if (aes_table.cases[i].n_plants)
			any_plant = 1;
	for (i = 0; i < aes_table.prelude_count; i++)
		if (aes_table.preludes[i].n_plants)
			any_plant = 1;

	if (aes_table.prelude_count && any_plant)
		imports = "use crate::harness::{check, Call, Case, Kind, Plant, Reset, "
		          "Table};\n";
	else if (aes_table.prelude_count)
		imports = "use crate::harness::{check, Call, Case, Reset, Table};\n";
	else if (any_plant)
		imports = "use crate::harness::{check, Case, Kind, Plant, Reset, Table};\n";
	else
		imports = "use crate::harness::{check, Case, Reset, Table};\n";

	addrin_note = aes_table.columns == TD_AES_CASE_COLUMNS_MAX
	    ? "//!\n"
	      "//! `plant` is the table's EIGHTH column, its `addr_in` column: it names\n"
	      "//! one of the dumper's four buffers BY NUMBER, never an address -- one\n"
	      "//! case table is carried to two machines and an address is different on\n"
	      "//! each. The harness holds the same four buffers, the same size and the\n"
	      "//! same bytes (`harness::buf_fill`), and a slot that still holds what was\n"
	      "//! planted compares as the buffer token both sides record\n"
	      "//! (`tosdump/core/tosdump.h`, `TD_AES_ADDR_TOKEN`).\n"
	    : "";

	fprintf(f,
"//! GENERATED by tosdump/host/mkrusttests -- do not edit.\n"
"//!\n"
"//! One test per case in `%s`, replayed against `tos_api::aes` and\n"
"//! compared with what a real machine did, recorded in `%s`\n"
"//! (build %s, case table CRC %08X, %u cases).\n"
"//!\n"
"//! The expected values are not written out here: the dump is embedded and\n"
"//! indexed, so it stays the single source of truth and a regenerated file\n"
"//! cannot carry stale expectations. Regenerate with:\n"
"//!\n"
"//!     tosdump/host/build/mkrusttests \\\\\n"
"//!         %s \\\\\n"
"//!         %s \\\\\n"
"//!         %s \\\\\n"
"//!         %s\n"
"//!\n"
"//! `in_len`/`out_len`/`ain_len`/`aout_len` are `control[1..4]` as the case\n"
"//! table declares them, NOT counts derived from the value list: the AES\n"
"//! dispatcher marshals by the declared counts alone, and several cases\n"
"//! exist precisely to measure a count that disagrees with the values\n"
"//! (`aes/gemsuper.c:428-448`).\n"
"%s"
"\n"
"%s"
"\n"
"static DUMP: &[u8] = include_bytes!(\"%s\");\n"
"\n"
"/// The table this dump was produced from: its name, because a case id is a\n"
"/// physical line number in THAT file and two tables reuse ids; and the reset\n"
"/// its own `!reset` directive line declares, which the harness issues before\n"
"/// every case exactly as `tosdump/core/runner_aes.c:154` does.\n"
"static TABLE: Table = Table {\n"
"    name: \"%s\",\n"
"    dump: DUMP,\n"
"    reset: Reset::%s,\n"
"};\n",
	        cases_path, dump_path, h->build_id, h->case_crc, h->record_count,
	        cases_path, dump_path, include_path, out_path, addrin_note,
	        imports, include_path, cases_path, reset_name);

	for (i = 0; i < aes_table.count; i++) {
		const struct td_aes_case *c = &aes_table.cases[i];
		char name[96], cmt[TD_COMMENT_LEN * 2];

		slug(c->comment, name, sizeof name);
		escape(c->comment, cmt, sizeof cmt);

		fprintf(f, "\n#[test]\nfn case_%04u_op%03d_%s() {\n", c->line,
		        c->opcode, name);
		fprintf(f, "    check(&TABLE, &Case {\n");
		fprintf(f, "        prelude: &[");
		{
			uint16_t k;
			for (k = 0; k < c->prelude_count; k++) {
				const struct td_aes_prelude *p =
					&aes_table.preludes[c->prelude_first + k];
				fprintf(f, "\n            Call { opcode: %d, in_len: %d, "
				           "out_len: %d, ain_len: %d, aout_len: %d, intin: ",
				        p->opcode, p->n_intin, p->n_intout, p->n_addrin,
				        p->n_addrout);
				emit_list(f, p->intin, p->n_values);
				fprintf(f, ", plant: ");
				emit_plants(f, p->plant, p->n_plants);
				fprintf(f, " },");
			}
			if (c->prelude_count)
				fprintf(f, "\n        ");
		}
		fprintf(f, "],\n");
		fprintf(f, "        id: %u,\n        rec: %u,\n", c->line, i);
		fprintf(f, "        opcode: %d,\n", c->opcode);
		fprintf(f, "        in_len: %d,\n        out_len: %d,\n",
		        c->n_intin, c->n_intout);
		fprintf(f, "        ain_len: %d,\n        aout_len: %d,\n",
		        c->n_addrin, c->n_addrout);
		fprintf(f, "        intin: ");
		emit_list(f, c->intin, c->n_values);
		fprintf(f, ",\n        plant: ");
		emit_plants(f, c->plant, c->n_plants);
		fprintf(f, ",\n        comment: \"%s\",\n    });\n}\n", cmt);
	}
	return (int)aes_table.count;
}

/* ------------------------------------------------------------------ */
/* VDI raster emitter                                                  */
/* ------------------------------------------------------------------ */
/*
 * The raster case carries two FORMS and two FILL SEEDS on top of the usual
 * opcode/INTIN/PTSIN, and that is the whole difference to the VDI form: a
 * raster call's result is memory, so the operand has to be laid before the
 * call and read back after it (core/runner_rast.c).  A form is emitted as
 * the case table states it -- buffer, fd_w, fd_h, fd_wdwidth, fd_stand,
 * fd_nplanes -- and never as an address: naming a buffer is what lets both
 * MFDBs name the SAME one, which is how the in-place vr_trnfm cases are
 * stated, and an address could not be the same on two machines anyway.
 *
 * There is no sub-opcode and no prelude column: none of the three raster
 * opcodes is an escape, and the loader refuses a '+' line outright
 * (core/cases.h), so `Call` is never imported here.
 */
static int emit_raster(FILE *f, const struct td_header *h, const char *cases_path,
                       const char *dump_path, const char *include_path,
                       const char *out_path)
{
	uint16_t i;

	fprintf(f,
"//! GENERATED by tosdump/host/mkrusttests -- do not edit.\n"
"//!\n"
"//! One test per case in `%s`, replayed against `tos_api::vdi` and\n"
"//! compared with what a real machine did, recorded in `%s`\n"
"//! (build %s, case table CRC %08X, %u cases).\n"
"//!\n"
"//! The expected values are not written out here: the dump is embedded and\n"
"//! indexed, so it stays the single source of truth and a regenerated file\n"
"//! cannot carry stale expectations. Regenerate with:\n"
"//!\n"
"//!     tosdump/host/build/mkrusttests \\\\\n"
"//!         %s \\\\\n"
"//!         %s \\\\\n"
"//!         %s \\\\\n"
"//!         %s\n"
"//!\n"
"//! `src`/`dst` are the two forms as the case table states them -- a BUFFER\n"
"//! and the five WORD fields of an MFDB, never an address, so both forms may\n"
"//! name the same buffer (the in-place `vr_trnfm` cases). `seed_a`/`seed_b`\n"
"//! lay the two pixel buffers before the call; the operand of a raster call\n"
"//! is memory, so it has to be laid rather than poisoned\n"
"//! (`tosdump/core/runner_rast.c`).\n"
"\n"
"use crate::harness::{check, Case, Form};\n"
"\n"
"static DUMP: &[u8] = include_bytes!(\"%s\");\n",
	        cases_path, dump_path, h->build_id, h->case_crc, h->record_count,
	        cases_path, dump_path, include_path, out_path, include_path);

	for (i = 0; i < rast_table.count; i++) {
		const struct td_rast_case *c = &rast_table.cases[i];
		char name[96], cmt[TD_COMMENT_LEN * 2];

		slug(c->comment, name, sizeof name);
		escape(c->comment, cmt, sizeof cmt);

		fprintf(f, "\n#[test]\nfn case_%04u_op%03d_%s() {\n", c->line,
		        c->opcode, name);
		fprintf(f, "    check(DUMP, &Case {\n");
		fprintf(f, "        id: %u,\n        rec: %u,\n", c->line, i);
		fprintf(f, "        opcode: %d,\n", c->opcode);
		fprintf(f, "        intin: ");
		emit_list(f, c->intin, c->n_intin);
		fprintf(f, ",\n        ptsin: ");
		emit_list(f, c->ptsin, c->n_ptsin);
		fprintf(f, ",\n        src: ");
		emit_form(f, &c->src);
		fprintf(f, ",\n        dst: ");
		emit_form(f, &c->dst);
		fprintf(f, ",\n        seed_a: %u,\n        seed_b: %u,\n",
		        c->seed_a, c->seed_b);
		fprintf(f, "        comment: \"%s\",\n    });\n}\n", cmt);
	}
	return (int)rast_table.count;
}

int main(int argc, char **argv)
{
	struct td_case_error err;
	struct td_header h;
	uint8_t hdr[TD_HEADER_SIZE];
	const char *cases_path, *dump_path, *include_path, *out_path;
	FILE *fd, *f;
	uint32_t table_crc;
	uint16_t table_count;
	int rc, n;

	if (argc != 5) {
		fprintf(stderr, "usage: mkrusttests CASES.TSV DUMP.BIN "
		                "DUMP_INCLUDE_PATH OUT.rs\n");
		return 2;
	}
	cases_path = argv[1];
	dump_path = argv[2];
	include_path = argv[3];
	out_path = argv[4];

	/* The dump comes first: its header states the area, and the area
	 * decides which case-table form to read.  Reading the table first and
	 * checking the area afterwards would mis-slice every line of an AES
	 * table with the five-column VDI rule. */
	fd = fopen(dump_path, "rb");
	if (!fd || fread(hdr, 1, sizeof hdr, fd) != sizeof hdr) {
		fprintf(stderr, "%s: cannot read the dump header\n", dump_path);
		if (fd) fclose(fd);
		return 1;
	}
	fclose(fd);
	rc = td_header_parse(hdr, sizeof hdr, &h);
	if (rc != 0) {
		fprintf(stderr, "%s: malformed header (%d)\n", dump_path, rc);
		return 1;
	}
	if (h.area != TD_AREA_VDI && h.area != TD_AREA_AES &&
	    h.area != TD_AREA_RASTER) {
		fprintf(stderr, "refusing: %s is area %s -- no emitter for it\n",
		        dump_path, td_area_name(h.area));
		return 2;
	}

	memset(&err, 0, sizeof err);
	if (h.area == TD_AREA_VDI) {
		rc = td_cases_load(&table, cases_path, &err);
		table_crc = table.crc;
		table_count = table.count;
	} else if (h.area == TD_AREA_AES) {
		rc = td_aes_cases_load(&aes_table, cases_path, &err);
		table_crc = aes_table.crc;
		table_count = aes_table.count;
	} else {
		rc = td_rast_cases_load(&rast_table, cases_path, &err);
		table_crc = rast_table.crc;
		table_count = rast_table.count;
	}
	if (rc != 0) {
		if (err.line)
			fprintf(stderr, "%s line %u: %s (%s)\n", cases_path, err.line,
			        err.what ? err.what : "", td_case_error_text(rc));
		else
			fprintf(stderr, "%s: %s\n", cases_path, td_case_error_text(rc));
		return 1;
	}

	/* Refuse rather than generate nonsense: a dump taken with a different
	 * case table has different case ids at every index. */
	if (h.case_crc != table_crc) {
		fprintf(stderr,
		        "refusing: %s carries case table CRC %08X, %s is %08X -- the "
		        "dump was not produced from this table\n",
		        dump_path, h.case_crc, cases_path, table_crc);
		return 2;
	}
	if (h.record_count != table_count) {
		fprintf(stderr, "refusing: %s holds %u records, %s holds %u cases\n",
		        dump_path, h.record_count, cases_path, table_count);
		return 2;
	}

	f = fopen(out_path, "wb");
	if (!f) {
		perror(out_path);
		return 1;
	}

	if (h.area == TD_AREA_VDI)
		n = emit_vdi(f, &h, cases_path, dump_path, include_path,
		             out_path);
	else if (h.area == TD_AREA_AES)
		n = emit_aes(f, &h, cases_path, dump_path, include_path,
		             out_path);
	else
		n = emit_raster(f, &h, cases_path, dump_path, include_path,
		                out_path);

	fclose(f);
	/* An emitter refuses rather than writing a module that would replay the
	 * table differently than the dump was taken -- an AES table whose
	 * "!reset" names something this generator has no Rust name for
	 * (emit_aes). */
	if (n < 0) {
		fprintf(stderr, "refusing: %s %s\n", cases_path,
		        emit_refusal ? emit_refusal
		                     : "cannot be emitted by this generator");
		remove(out_path);
		return 2;
	}
	printf("%s: %d %s tests from %s\n", out_path, n, td_area_name(h.area),
	       dump_path);
	return 0;
}
